package directread

// Operation policy: the runtime loader of contracts/mcp/operations.v1.json
// (CHAOS-7036 design sections D.3 to D.7, table K14-A; slice S1a).
//
// The artifact is GENERATED by cmd/operationpolicy from the vendored ops
// catalogue (contracts/mcp/ops-catalogue/registry.v1.json + schema.graphql)
// and a hand-authored policy declaration. A byte-identical copy lives beside
// this file (operations.v1.json) so it can be embedded; a test holds the two
// equal and `go run ./cmd/operationpolicy -check` holds both equal to a fresh
// generation.
//
// Exported API (names are stable; the edge validator codes against them):
//
//	Loading
//	  DefaultCatalogue() (*Catalogue, error)   the embedded artifact, loaded once
//	  LoadCatalogue(data []byte) (*Catalogue, error)
//	  EmbeddedCatalogueJSON() []byte
//
//	Catalogue
//	  (*Catalogue).Lookup(name) (*OperationPolicy, *Refusal)
//	      a name that is not a served operation (a mutation, busFactor, a
//	      typo) is Refusal{Code: RefusalUnknownOperation}; for a listed
//	      not-served operation the Reason carries the recorded reason.
//	  (*Catalogue).LookupFor(name, CallerClass) (*OperationPolicy, CallerScope, *Refusal)
//	      adds RefusalOperationNotServedForCaller for a class the operation
//	      is refused to.
//	  (*Catalogue).Operations(CallerClass) []*OperationPolicy   sorted by name
//	  (*Catalogue).NotServed() []NotServedOperation
//	  (*Catalogue).SchemaDigest() string    ops goapidigest.Schema of the SDL
//	  (*Catalogue).Source() CatalogueSource
//
//	OperationPolicy (one served operation)
//	  Name, DocumentOperationName, Kind, Digest, DocumentText, CostClass,
//	  DeadlineSeconds, MaxInFlightPerOrg, Variables, PersonVariables,
//	  Constraints, Scopes, Outputs, WithheldOutputs, Disclosure
//	  (*OperationPolicy).Variable(path) (VariableRule, bool)
//	  (*OperationPolicy).Scope(CallerClass) CallerScope
//	  (*OperationPolicy).OutputAllowed(path) bool
//	  (*OperationPolicy).Completeness(data []byte) Completeness
//	  FilterResponse(op, data) (FilterResult, error)
//	      removes every response path the allowlist does not list; the
//	      caller ERROR-logs FilterResult.RemovedPaths / RemovedValues.
//
//	Variable rules (VariableRule): every input path the SDL allows for the
//	operation's variables, arrays as [*], objects included (Kind "object").
//	A rule with Allowed=false must be absent or JSON null in a request; its
//	Refusal says which code to answer. Source says who sets the value:
//	client, acr_principal_org (orgId from the principal, never the client),
//	acr_forced (ForcedValue). Enum rules carry AllowedValues and
//	RefusedValues (value -> code). Min/Max, MaxItems, MaxLength are clamps.
//	Subject (SubjectConversion) converts an acr subject id to the ops form:
//	(SubjectConversion).ToOps(acrID) (string, error).
//
//	Request-check rules the validator applies (allowlist semantics):
//	  - a request path with no rule is refused (variable_not_allowed);
//	  - a present, non-null path whose rule has Allowed=false is refused
//	    with that rule's Refusal; when several refused paths are present,
//	    report the DEEPEST one (who.developers answers
//	    person_scope_not_served, not the "who" object's code);
//	  - an enum value in RefusedValues answers that entry's code; a value
//	    in neither AllowedValues nor RefusedValues is variable_not_allowed;
//	  - Min/Max bound integers, MaxItems bounds lists, MaxLength bounds
//	    each string (variable_out_of_range);
//	  - acr_principal_org and acr_forced values are set by acr; a client
//	    value on such a path is refused (variable_not_allowed);
//	  - for a restricted caller, CallerScope.ForcedVariablePath is set to
//	    the grant intersection (converted with the rule's Subject); an
//	    empty intersection ends before dispatch (no_granted_scope); each
//	    RowIDPaths value of the answer must be in the grant, else the whole
//	    answer is refused (row_outside_grant).
//
//	Constraints (Constraint, kinds ConstraintRequired, ConstraintRequiresValue,
//	ConstraintEmptyOrAbsent, ConstraintWindowMaxDays, ConstraintMaxDaysAhead)
//	are cross-path rules; each carries its refusal Code and Reason.
//
//	Vocabularies: RefusalCode (RefusalCodeVocabulary), CallerClass,
//	CostClass, ConstraintKind, OutputLeaf, DisclosureRule, VariableSource;
//	status vocabulary in status.go (CallStatus, Completeness, ResultState).
//
//	Helpers shared with the generator: DocumentDigest, SchemaDigestOf,
//	ParseRegisteredDocument, IsPersonNamed, PersonNameTokens,
//	CallerClassFor(PrincipalClass).
//
// Load is fail closed: every served document is PARSED again, and must hold
// exactly one operation, of kind query, whose name equals the declared
// document_operation_name; its digest is recomputed and compared. Any
// violation, and any structural defect (unknown vocabulary, a person-named
// or free-JSON output path without a written exception, a row id path that
// is not an allowed output) is a load error. No network is used.

import (
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"sort"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/vektah/gqlparser/v2/ast"
	"github.com/vektah/gqlparser/v2/parser"
)

// OperationCatalogueContract is the contract name the artifact carries.
const OperationCatalogueContract = "acr.mcp.operations.v1"

// BasisDependentShapeText is the fixed refusal text of table K14-A.
const BasisDependentShapeText = "team and repository investment comes from read_facts (kind investment)"

//go:embed operations.v1.json
var embeddedCatalogue []byte

// EmbeddedCatalogueJSON returns a copy of the embedded artifact bytes.
func EmbeddedCatalogueJSON() []byte { return bytes.Clone(embeddedCatalogue) }

// RefusalCode is the closed vocabulary of typed refusals of the data path.
type RefusalCode string

const (
	RefusalUnknownOperation            RefusalCode = "unknown_operation"
	RefusalVariableNotAllowed          RefusalCode = "variable_not_allowed"
	RefusalVariableOutOfRange          RefusalCode = "variable_out_of_range"
	RefusalPersonScopeNotServed        RefusalCode = "person_scope_not_served"
	RefusalBasisDependentShape         RefusalCode = "basis_dependent_shape"
	RefusalNoGrantedScope              RefusalCode = "no_granted_scope"
	RefusalOperationNotServedForCaller RefusalCode = "operation_not_served_for_caller"
	RefusalResponseBudget              RefusalCode = "response_budget"
	RefusalInvalidRequest              RefusalCode = "invalid_request"
	RefusalScopeRequired               RefusalCode = "scope_required"
	RefusalRowOutsideGrant             RefusalCode = "row_outside_grant"
	RefusalPolicyStale                 RefusalCode = "policy_stale"
)

// RefusalCodeVocabulary is the closed set of refusal codes.
func RefusalCodeVocabulary() [12]RefusalCode {
	return [12]RefusalCode{
		RefusalUnknownOperation, RefusalVariableNotAllowed, RefusalVariableOutOfRange,
		RefusalPersonScopeNotServed, RefusalBasisDependentShape, RefusalNoGrantedScope,
		RefusalOperationNotServedForCaller, RefusalResponseBudget, RefusalInvalidRequest,
		RefusalScopeRequired, RefusalRowOutsideGrant, RefusalPolicyStale,
	}
}

// Refusal is a typed, terminal refusal. It is never turned into empty data.
type Refusal struct {
	Code   RefusalCode `json:"code"`
	Reason string      `json:"reason"`
}

func (r *Refusal) Error() string { return string(r.Code) + ": " + r.Reason }

// CallerClass is the policy's view of a principal: unrestricted (no grant
// list, or the "*" grant) or restricted (a specific repository grant).
type CallerClass string

const (
	CallerUnrestricted CallerClass = "unrestricted"
	CallerRestricted   CallerClass = "restricted"
)

// CallerClassVocabulary is the closed set of caller classes.
func CallerClassVocabulary() [2]CallerClass {
	return [2]CallerClass{CallerUnrestricted, CallerRestricted}
}

// CallerClassFor maps the subject gate's principal class onto the policy's
// caller class: unrestricted and universal ("*") callers are unrestricted.
// Any unknown class is restricted (fail closed).
func CallerClassFor(class PrincipalClass) CallerClass {
	switch class {
	case ClassUnrestricted, ClassUniversal:
		return CallerUnrestricted
	default:
		return CallerRestricted
	}
}

// CostClass is the D.6 cost class.
type CostClass string

const (
	CostCompute        CostClass = "compute"
	CostAnalyticsBatch CostClass = "analytics_batch"
	CostList           CostClass = "list"
	CostSeries         CostClass = "series"
	CostCatalog        CostClass = "catalog"
)

// CostClassVocabulary is the closed set of cost classes.
func CostClassVocabulary() [5]CostClass {
	return [5]CostClass{CostCompute, CostAnalyticsBatch, CostList, CostSeries, CostCatalog}
}

// VariableSource says who sets a variable value.
type VariableSource string

const (
	SourceClient       VariableSource = "client"
	SourcePrincipalOrg VariableSource = "acr_principal_org"
	SourceForced       VariableSource = "acr_forced"
	SourceNotSettable  VariableSource = "none"
)

// Variable rule kinds and subject kinds.
const (
	VariableKindScalar    = "scalar"
	VariableKindEnum      = "enum"
	VariableKindObject    = "object"
	SubjectKindRepository = "repository"
	SubjectKindTeam       = "team"
)

// ConstraintKind is the closed vocabulary of cross-path constraints.
type ConstraintKind string

const (
	// ConstraintRequired: Path must be present and not null.
	ConstraintRequired ConstraintKind = "required"
	// ConstraintRequiresValue: when Path is present and not null, the value
	// at Other (or OtherDefault when Other is absent) must be in Values.
	// With an empty Path the rule is unconditional: Other must be in Values.
	ConstraintRequiresValue ConstraintKind = "requires_value"
	// ConstraintEmptyOrAbsent: Path must be absent, null or an empty list.
	ConstraintEmptyOrAbsent ConstraintKind = "empty_or_absent"
	// ConstraintWindowMaxDays: Path is the window start, Other the end
	// (absent end = now). end >= start and end - start <= MaxDays. An
	// absent start is refused unless AllowOpenStart.
	ConstraintWindowMaxDays ConstraintKind = "window_max_days"
	// ConstraintMaxDaysAhead: the date at Path is at most MaxDays after now.
	ConstraintMaxDaysAhead ConstraintKind = "max_days_ahead"
)

// ConstraintKindVocabulary is the closed set of constraint kinds.
func ConstraintKindVocabulary() [5]ConstraintKind {
	return [5]ConstraintKind{ConstraintRequired, ConstraintRequiresValue, ConstraintEmptyOrAbsent, ConstraintWindowMaxDays, ConstraintMaxDaysAhead}
}

// OutputLeaf classifies an allowlisted response path.
type OutputLeaf string

const (
	LeafScalar   OutputLeaf = "scalar"
	LeafJSON     OutputLeaf = "json"
	LeafTypename OutputLeaf = "typename"
)

// DisclosureRule is how a disclosure field maps to Completeness.
type DisclosureRule string

const (
	// DisclosurePartialWhenNonNull: a non-null value = declared_partial.
	DisclosurePartialWhenNonNull DisclosureRule = "partial_when_non_null"
	// DisclosurePartialWhenTrue: the value true = declared_partial.
	DisclosurePartialWhenTrue DisclosureRule = "partial_when_true"
	// DisclosurePartialWhenBelowOne: a number below 1 = declared_partial.
	DisclosurePartialWhenBelowOne DisclosureRule = "partial_when_below_one"
)

