// NotServedOperation is a registered ops document that the MCP surface does
// not serve, with the reason.
type NotServedOperation struct {
	Name   string      `json:"name"`
	Kind   string      `json:"kind"`
	Digest string      `json:"digest"`
	Code   RefusalCode `json:"code"`
	Reason string      `json:"reason"`
}

// EffectiveDefault is the default a client can rely on when it omits the
// variable: the generated SDL default, moved into [Min, Max] for an integer.
// data_catalog, the schema view and the cost clamp all read it, so the
// advertised value and the applied value cannot differ.
func (r VariableRule) EffectiveDefault() string {
	if baseTypeName(r.Type) != "Int" {
		return r.Default
	}
	var v int64
	if _, err := fmt.Sscan(r.Default, &v); err != nil || fmt.Sprint(v) != r.Default {
		return r.Default
	}
	if r.Max != nil && v > *r.Max {
		v = *r.Max
	}
	if r.Min != nil && v < *r.Min {
		v = *r.Min
	}
	return fmt.Sprint(v)
}

// Catalogue is a loaded, validated artifact.
type Catalogue struct {
	file      CatalogueFile
	byName    map[string]*OperationPolicy
	notServed map[string]NotServedOperation
	// watch is the optional served-registry check (registry_watch.go).
	watch atomic.Pointer[RegistryWatch]
}

var (
	defaultCatalogueOnce sync.Once
	defaultCatalogue     *Catalogue
	defaultCatalogueErr  error
)

// DefaultCatalogue loads the embedded artifact once.
func DefaultCatalogue() (*Catalogue, error) {
	defaultCatalogueOnce.Do(func() {
		defaultCatalogue, defaultCatalogueErr = LoadCatalogue(embeddedCatalogue)
	})
	return defaultCatalogue, defaultCatalogueErr
}

// ErrCatalogueInvalid wraps every load failure.
var ErrCatalogueInvalid = errors.New("operation catalogue invalid")

func loadErr(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrCatalogueInvalid, fmt.Sprintf(format, args...))
}

// LoadCatalogue parses and validates an artifact. It is fail closed.
func LoadCatalogue(data []byte) (*Catalogue, error) {
	var file CatalogueFile
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&file); err != nil {
		return nil, loadErr("decode: %v", err)
	}
	if file.Contract != OperationCatalogueContract {
		return nil, loadErr("contract %q, want %q", file.Contract, OperationCatalogueContract)
	}
	if !slices.Equal(file.PersonNameTokens, PersonNameTokens()) {
		return nil, loadErr("person_name_tokens differ from the loader's list")
	}
	c := &Catalogue{file: file, byName: map[string]*OperationPolicy{}, notServed: map[string]NotServedOperation{}}
	for i := range c.file.Operations {
		op := &c.file.Operations[i]
		if err := validateOperation(op); err != nil {
			return nil, loadErr("operation %q: %v", op.Name, err)
		}
		if _, dup := c.byName[op.Name]; dup {
			return nil, loadErr("operation %q listed twice", op.Name)
		}
		c.byName[op.Name] = op
	}
	for _, ns := range c.file.NotServed {
		if ns.Name == "" || ns.Reason == "" || !knownRefusalCode(ns.Code) {
			return nil, loadErr("not_served entry %q lacks a name, a reason or a known code", ns.Name)
		}
		if _, dup := c.byName[ns.Name]; dup {
			return nil, loadErr("operation %q is both served and not served", ns.Name)
		}
		if _, dup := c.notServed[ns.Name]; dup {
			return nil, loadErr("not_served %q listed twice", ns.Name)
		}
		c.notServed[ns.Name] = ns
	}
	if got := len(c.byName) + len(c.notServed); got != file.Source.RegistryRows {
		return nil, loadErr("%d operations classified, registry has %d rows", got, file.Source.RegistryRows)
	}
	return c, nil
}

// RegisteredDocument is what ParseRegisteredDocument reports.
type RegisteredDocument struct {
	Kind string
	Name string
}

// Document kinds (the ops goapidigest.DocumentKind vocabulary).
const (
	DocumentKindQuery    = "query"
	DocumentKindMutation = "mutation"
)

// ParseRegisteredDocument is acr's copy of ops goapidigest.DocumentKind
// (internal/goapidigest/kind.go:28-44 at ops 9dffd5f77), plus the operation
// name: exactly one operation, of kind query or mutation. Anything else
// (unparseable, zero or several operations, a subscription) is an error.
func ParseRegisteredDocument(text string) (RegisteredDocument, error) {
	doc, err := parser.ParseQuery(&ast.Source{Name: "registered document", Input: text})
	if err != nil {
		return RegisteredDocument{}, fmt.Errorf("document does not parse: %w", err)
	}
	if len(doc.Operations) != 1 {
		return RegisteredDocument{}, fmt.Errorf("document has %d operations, want exactly 1", len(doc.Operations))
	}
	op := doc.Operations[0]
	switch op.Operation {
	case ast.Query:
		return RegisteredDocument{Kind: DocumentKindQuery, Name: op.Name}, nil
	case ast.Mutation:
		return RegisteredDocument{Kind: DocumentKindMutation, Name: op.Name}, nil
	default:
		return RegisteredDocument{}, fmt.Errorf("document operation type %q is not served by query-api", op.Operation)
	}
}

// DocumentDigest is acr's copy of ops goapidigest.Document: the hex sha256
// of strings.TrimSpace(text).
func DocumentDigest(text string) string {
	sum := sha256.Sum256([]byte(strings.TrimSpace(text)))
	return hex.EncodeToString(sum[:])
}

// SchemaDigestOf is acr's copy of ops goapidigest.Schema: "sha256:" + the
// hex sha256 of the RAW SDL bytes.
func SchemaDigestOf(sdl []byte) string {
	sum := sha256.Sum256(sdl)
	return "sha256:" + hex.EncodeToString(sum[:])
}

// personNameTokens is design D.5's list of person-named path segments. A
// segment matches when its lower-cased form CONTAINS a token, so plurals
// and compounds (topMaintainers, developers, triggeredBy's "createdby" kin)
// match too. Over-matching fails closed: it forces a written exception.
var personNameTokens = []string{
	"actor", "assignee", "author", "committer", "createdby", "developer",
	"email", "identity", "login", "maintainer", "reviewer", "user",
}

// PersonNameTokens returns the person-name tokens.
func PersonNameTokens() []string { return slices.Clone(personNameTokens) }

// IsPersonNamed reports whether a path segment (field name, enum value or
// input field name) names a person.
func IsPersonNamed(segment string) bool {
	lower := strings.ToLower(segment)
	for _, token := range personNameTokens {
		if strings.Contains(lower, token) {
			return true
		}
	}
	return false
}

// pathSegments splits "a.b[*].c" into field names ("a", "b", "c").
func pathSegments(path string) []string {
	parts := strings.Split(strings.ReplaceAll(path, "[*]", ""), ".")
	return parts
}

func validateOperation(op *OperationPolicy) error {
	if op.Name == "" || op.DocumentOperationName == "" {
		return errors.New("name or document_operation_name empty")
	}
	if op.Kind != DocumentKindQuery {
		return fmt.Errorf("declared kind %q, want query", op.Kind)
	}
	parsed, err := ParseRegisteredDocument(op.DocumentText)
	if err != nil {
		return err
	}
	if parsed.Kind != DocumentKindQuery {
		return fmt.Errorf("document parses as %s, want query", parsed.Kind)
	}
	if parsed.Name != op.DocumentOperationName {
		return fmt.Errorf("document operation name %q, declared %q", parsed.Name, op.DocumentOperationName)
	}
	if got := DocumentDigest(op.DocumentText); got != op.Digest {
		return fmt.Errorf("digest %s, recomputed %s", op.Digest, got)
	}
	if !knownCostClass(op.CostClass) {
		return fmt.Errorf("cost class %q not in vocabulary", op.CostClass)
	}
	if op.DeadlineSeconds <= 0 {
		return errors.New("deadline_seconds must be positive")
	}
	op.variables = map[string]int{}
	for i, v := range op.Variables {
		if _, dup := op.variables[v.Path]; dup {
			return fmt.Errorf("variable %q listed twice", v.Path)
		}
		op.variables[v.Path] = i
		if v.Allowed == (v.Refusal != nil) {
			return fmt.Errorf("variable %q: allowed and refusal must be exclusive", v.Path)
		}
		if v.Refusal != nil && !knownRefusalCode(v.Refusal.Code) {
			return fmt.Errorf("variable %q: refusal code %q not in vocabulary", v.Path, v.Refusal.Code)
		}
		if v.Allowed && v.Source == SourceNotSettable {
			return fmt.Errorf("variable %q: allowed with source none", v.Path)
		}
		for _, rv := range v.RefusedValues {
			if !knownRefusalCode(rv.Code) || slices.Contains(v.AllowedValues, rv.Value) {
				return fmt.Errorf("variable %q: refused value %q invalid", v.Path, rv.Value)
			}
		}
		for _, av := range v.AllowedValues {
			if !slices.Contains(v.Enum, av) {
				return fmt.Errorf("variable %q: allowed value %q not in the enum", v.Path, av)
			}
		}
	}
	for _, pv := range op.PersonVariables {
		i, ok := op.variables[pv.Path]
		if !ok {
			return fmt.Errorf("person variable %q is not a listed path", pv.Path)
		}
		rule := op.Variables[i]
		if pv.Value == "" && rule.Allowed {
			return fmt.Errorf("person variable %q is allowed", pv.Path)
		}
		if pv.Value != "" && slices.Contains(rule.AllowedValues, pv.Value) {
			return fmt.Errorf("person value %s=%s is allowed", pv.Path, pv.Value)
		}
	}
	for _, v := range op.Variables {
		if v.Allowed && v.Kind == VariableKindEnum && len(v.AllowedValues) == 0 {
			return fmt.Errorf("enum variable %q allowed with no allowed values", v.Path)
		}
		for _, av := range v.AllowedValues {
			if IsPersonNamed(av) {
				return fmt.Errorf("person value %s=%s is allowed", v.Path, av)
			}
		}
		if v.Allowed && slices.ContainsFunc(pathSegments(v.Path), IsPersonNamed) {
			return fmt.Errorf("person-named variable %q is allowed", v.Path)
		}
	}
	allConstraints := slices.Clone(op.Constraints)
	op.outputs = map[string]OutputLeaf{}
	op.nodes = map[string]bool{}
	for _, out := range op.Outputs {
		if _, dup := op.outputs[out.Path]; dup {
			return fmt.Errorf("output %q listed twice", out.Path)
		}
		switch out.Leaf {
		case LeafScalar, LeafTypename:
		case LeafJSON:
			if out.Exception == "" {
				return fmt.Errorf("free JSON output %q without a written exception", out.Path)
			}
		default:
			return fmt.Errorf("output %q: leaf %q not in vocabulary", out.Path, out.Leaf)
		}
		if slices.ContainsFunc(pathSegments(out.Path), IsPersonNamed) && out.Exception == "" {
			return fmt.Errorf("person-named output %q without a written exception", out.Path)
		}
		op.outputs[out.Path] = out.Leaf
		for prefix := parentPath(out.Path); prefix != ""; prefix = parentPath(prefix) {
			op.nodes[prefix] = true
		}
	}
	if len(op.outputs) == 0 {
		return errors.New("no output path")
	}
	for _, w := range op.WithheldOutputs {
		if _, listed := op.outputs[w.Path]; listed || w.Reason == "" {
			return fmt.Errorf("withheld output %q is also allowed or has no reason", w.Path)
		}
	}
	for _, d := range op.Disclosure {
		if _, ok := op.outputs[d.Path]; !ok {
			return fmt.Errorf("disclosure field %q is not an allowed output", d.Path)
		}
	}
	seen := map[CallerClass]bool{}
	for _, s := range op.Scopes {
		if !knownCallerClass(s.Caller) || seen[s.Caller] {
			return fmt.Errorf("scope caller %q unknown or repeated", s.Caller)
		}
		seen[s.Caller] = true
		if s.Served == (s.Refusal != nil) {
			return fmt.Errorf("scope %q: served and refusal must be exclusive", s.Caller)
		}
		if s.Basis == "" {
			return fmt.Errorf("scope %q: no basis", s.Caller)
		}
		if s.Caller == CallerRestricted && s.Served {
			if s.ForcedVariablePath == "" || len(s.RowIDPaths) == 0 || s.SubjectKind != SubjectKindRepository {
				return errors.New("restricted scope served without forced repository path and row id paths")
			}
			forced, ok := op.Variable(s.ForcedVariablePath)
			if !ok {
				return fmt.Errorf("forced path %q is not a listed variable", s.ForcedVariablePath)
			}
			if !forced.Allowed || forced.Subject == nil || forced.Subject.Kind != SubjectKindRepository {
				return fmt.Errorf("forced path %q is not an allowed repository variable", s.ForcedVariablePath)
			}
			for _, row := range s.RowIDPaths {
				if op.outputs[row] != LeafScalar {
					return fmt.Errorf("row id path %q is not an allowed scalar output", row)
				}
			}
		}
		allConstraints = append(allConstraints, s.Constraints...)
	}
	if len(seen) != len(CallerClassVocabulary()) {
		return errors.New("scopes must cover every caller class")
	}
	if !seen[CallerUnrestricted] {
		return errors.New("no unrestricted scope")
	}
	if op.Scope(CallerUnrestricted).Refusal != nil {
		return errors.New("a served operation must be served to the unrestricted caller")
	}
	for _, con := range allConstraints {
		if !knownConstraintKind(con.Kind) || !knownRefusalCode(con.Code) || con.Reason == "" {
			return fmt.Errorf("constraint %s on %q: kind, code or reason invalid", con.Kind, con.Path)
		}
		for _, p := range []string{con.Path, con.Other} {
			if _, ok := op.variables[p]; p != "" && !ok {
				return fmt.Errorf("constraint %s names unknown path %q", con.Kind, p)
			}
		}
	}
	return nil
}

// parentPath returns the enclosing node of a path: "a.b[*].c" -> "a.b[*]"
// -> "a.b" -> "a" -> "".
func parentPath(path string) string {
	if trimmed, ok := strings.CutSuffix(path, "[*]"); ok {
		return trimmed
	}
	if i := strings.LastIndex(path, "."); i >= 0 {
		return path[:i]
	}
	return ""
}

// Source returns what the artifact was generated from.
func (c *Catalogue) Source() CatalogueSource { return c.file.Source }

// SchemaDigest returns the ops schema digest the artifact was generated
// against (ops goapidigest.Schema form).
func (c *Catalogue) SchemaDigest() string { return c.file.Source.SchemaDigest }

// Lookup returns the served operation, or a RefusalUnknownOperation refusal
// for any other name. It never dials anything.
func (c *Catalogue) Lookup(name string) (*OperationPolicy, *Refusal) {
	if op, ok := c.byName[name]; ok {
		return op, nil
	}
	if ns, ok := c.notServed[name]; ok {
		return nil, &Refusal{Code: RefusalUnknownOperation, Reason: ns.Reason}
	}
	return nil, &Refusal{Code: RefusalUnknownOperation, Reason: "operation is not in the served catalogue"}
}

// LookupFor is Lookup plus the caller-class rule.
func (c *Catalogue) LookupFor(name string, caller CallerClass) (*OperationPolicy, CallerScope, *Refusal) {
	op, refusal := c.Lookup(name)
	if refusal != nil {
		return nil, CallerScope{}, refusal
	}
	scope := op.Scope(caller)
	if !scope.Served {
		if scope.Refusal != nil {
			return nil, scope, scope.Refusal
		}
		return nil, scope, &Refusal{Code: RefusalOperationNotServedForCaller, Reason: "operation is not served to this caller class"}
	}
	return op, scope, nil
}

// Operations returns the operations served to a caller class, by name.
func (c *Catalogue) Operations(caller CallerClass) []*OperationPolicy {
	out := make([]*OperationPolicy, 0, len(c.byName))
	for _, op := range c.byName {
		if op.Scope(caller).Served {
			out = append(out, op)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// NotServed returns the registered operations the surface does not serve.
func (c *Catalogue) NotServed() []NotServedOperation { return slices.Clone(c.file.NotServed) }

// Variable returns the rule of one input path.
func (op *OperationPolicy) Variable(path string) (VariableRule, bool) {
	i, ok := op.variables[path]
	if !ok {
		return VariableRule{}, false
	}
	return op.Variables[i], true
}

// Scope returns the rule for a caller class. An unknown class is refused.
func (op *OperationPolicy) Scope(caller CallerClass) CallerScope {
	for _, s := range op.Scopes {
		if s.Caller == caller {
			return s
		}
	}
	return CallerScope{Caller: caller, Refusal: &Refusal{Code: RefusalOperationNotServedForCaller, Reason: "unknown caller class"}}
}

// OutputAllowed reports whether a response leaf path may leave acr.
func (op *OperationPolicy) OutputAllowed(path string) bool {
	_, ok := op.outputs[path]
	return ok
}

// FilterResult is what FilterResponse returns.
type FilterResult struct {
	// Data is the filtered "data" object.
	Data json.RawMessage
	// RemovedPaths are the distinct generalized paths ("a.b[*].c") removed.
	RemovedPaths []string
	// RemovedValues counts every removed value. Non-zero = ERROR log.
	RemovedValues int
}

// FilterResponse removes from a GraphQL "data" object every path that is
// not on the operation's output allowlist. A non-JSON leaf that carries an
// object or a list of objects is removed as well: an allowlisted scalar
// path never smuggles nested data. The caller ERROR-logs a non-zero result.
func FilterResponse(op *OperationPolicy, data []byte) (FilterResult, error) {
	if op == nil || op.outputs == nil {
		return FilterResult{}, errors.New("filter: operation policy not loaded")
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var root any
	if err := dec.Decode(&root); err != nil {
		return FilterResult{}, fmt.Errorf("filter: decode: %w", err)
	}
	f := &responseFilter{op: op, removed: map[string]bool{}}
	obj, ok := root.(map[string]any)
	if !ok {
		if root == nil {
			return FilterResult{Data: json.RawMessage("null")}, nil
		}
		return FilterResult{}, errors.New("filter: data is not an object")
	}
	kept := f.object("", obj)
	out, err := json.Marshal(kept)
	if err != nil {
		return FilterResult{}, fmt.Errorf("filter: encode: %w", err)
	}
	paths := make([]string, 0, len(f.removed))
	for p := range f.removed {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	return FilterResult{Data: out, RemovedPaths: paths, RemovedValues: f.count}, nil
}

type responseFilter struct {
	op      *OperationPolicy
	removed map[string]bool
	count   int
}

func joinPath(parent, key string) string {
	if parent == "" {
		return key
	}
	return parent + "." + key
}

func (f *responseFilter) remove(path string) {
	f.removed[path] = true
	f.count++
}

func (f *responseFilter) object(path string, obj map[string]any) map[string]any {
	out := make(map[string]any, len(obj))
	for key, value := range obj {
		child := joinPath(path, key)
		if kept, ok := f.value(child, value); ok {
			out[key] = kept
		}
	}
	return out
}

func (f *responseFilter) value(path string, value any) (any, bool) {
	leaf, isLeaf := f.op.outputs[path]
	if leaf == LeafJSON {
		// A free-JSON leaf is a written exception for a flat band -> number
		// map (ops investment/response.go:34,46). Anything richer could carry
		// a person field the path allowlist cannot see, so it is removed.
		if value != nil && !flatNumberMap(value) {
			f.remove(path)
			return nil, false
		}
		return value, true
	}
	switch v := value.(type) {
	case nil:
		if isLeaf || f.op.nodes[path] {
			return nil, true
		}
		f.remove(path)
		return nil, false
	case map[string]any:
		if !f.op.nodes[path] {
			f.remove(path)
			return nil, false
		}
		return f.object(path, v), true
	case []any:
		elem := path + "[*]"
		_, elemLeaf := f.op.outputs[elem]
		if !elemLeaf && !f.op.nodes[elem] {
			f.remove(path)
			return nil, false
		}
		out := make([]any, 0, len(v))
		for _, item := range v {
			if kept, ok := f.value(elem, item); ok {
				out = append(out, kept)
			}
		}
		return out, true
	default:
		if isLeaf {
			return v, true
		}
		f.remove(path)
		return nil, false
	}
}

// Completeness applies the operation's disclosure fields to a "data" object
// (D.7). Without a disclosure field the answer is always unknown.
func (op *OperationPolicy) Completeness(data []byte) Completeness {
	if len(op.Disclosure) == 0 {
		return CompletenessUnknown
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var root any
	if dec.Decode(&root) != nil {
		return CompletenessUnknown
	}
	for _, d := range op.Disclosure {
		value, present := lookupScalarPath(root, d.Path)
		if !present {
			continue
		}
		switch d.Rule {
		case DisclosurePartialWhenNonNull:
			if value != nil {
				return CompletenessDeclaredPartial
			}
		case DisclosurePartialWhenTrue:
			if b, ok := value.(bool); ok && b {
				return CompletenessDeclaredPartial
			}
		case DisclosurePartialWhenBelowOne:
			if n, ok := value.(json.Number); ok {
				if x, err := n.Float64(); err == nil && x < 1 {
					return CompletenessDeclaredPartial
				}
			}
		}
	}
	return CompletenessUnknown
}

func lookupScalarPath(root any, path string) (any, bool) {
	cur := root
	for _, seg := range strings.Split(path, ".") {
		obj, ok := cur.(map[string]any)
		if !ok {
			return nil, false
		}
		cur, ok = obj[seg]
		if !ok {
			return nil, false
		}
	}
	return cur, true
}

func knownRefusalCode(v RefusalCode) bool {
	vocab := RefusalCodeVocabulary()
	return slices.Contains(vocab[:], v)
}
func knownCostClass(v CostClass) bool {
	vocab := CostClassVocabulary()
	return slices.Contains(vocab[:], v)
}
func knownCallerClass(v CallerClass) bool {
	vocab := CallerClassVocabulary()
	return slices.Contains(vocab[:], v)
}
func knownConstraintKind(v ConstraintKind) bool {
	vocab := ConstraintKindVocabulary()
	return slices.Contains(vocab[:], v)
}

// flatNumberMap reports whether v is a JSON object whose keys are not
// person-named and whose values are all numbers or null (depth one). It is
// the only shape a free-JSON output leaf may have.
func flatNumberMap(v any) bool {
	obj, ok := v.(map[string]any)
	if !ok {
		return false
	}
	for key, value := range obj {
		if IsPersonNamed(key) {
			return false
		}
		switch value.(type) {
		case nil, json.Number, float64:
		default:
			return false
		}
	}
	return true
}
